const fs = require("fs");
const path = require("path");

// Data layer for /aspire-canberra-policy-lab. All numbers come from
// site-data/aspire-results.json (generated by scripts/aspire_analyze.py from
// the Pol.is report exports in data/aspire-canberra/) and
// site-data/aspire-qv-results.json (aggregate quadratic-vote totals only).
// Editorial copy lives in site-data/aspire-content.json and references
// statements by id only. See src/site/aspire-canberra-policy-lab/README.md.
const SITE_DATA = path.join(__dirname, "../../../site-data");

function readJson(name) {
  return JSON.parse(fs.readFileSync(path.join(SITE_DATA, name), "utf-8"));
}

module.exports = () => {
  const results = readJson("aspire-results.json");
  const content = readJson("aspire-content.json");
  const qv = readJson("aspire-qv-results.json");

  results.participation.total_votes_display =
    results.participation.total_votes.toLocaleString("en-US");

  // Rankings restricted to statements whose text is present in the export.
  const hasText = (id) => results.statements[String(id)].text;
  results.display_rankings = Object.fromEntries(
    Object.entries(results.rankings).map(([k, ids]) => [k, ids.filter(hasText)])
  );

  // Render-once rule: each statement gets exactly one card on the main page.
  // `carded` maps statement id -> true for every id that owns a card, so
  // reference links can resolve to the card anchor (#s<id>) on the main page
  // or to the row on /aspire-canberra-policy-lab/data/.
  const carded = {};
  const claim = (id) => {
    if (id == null) return;
    if (carded[id]) {
      throw new Error(
        `aspire content.json: statement [${id}] is assigned a card twice — ` +
          "the render-once rule requires a single canonical card per statement."
      );
    }
    carded[id] = true;
  };
  content.consensus.themes.forEach((t) => {
    claim(t.exemplar);
    (t.supporting || []).forEach(claim);
  });
  content.groups.list.forEach((g) => (g.cards || []).forEach(claim));
  if (content.uncommon) {
    content.uncommon.statements.forEach(claim);
    (content.uncommon.bridge ? content.uncommon.bridge.statements : []).forEach(claim);
  }
  content.carded = carded;

  // The uncommon-ground cards must stay in lockstep with the computed
  // cross-cutting flags — fail the build if editorial and analysis diverge.
  if (content.uncommon) {
    const computed = (results.rankings.cross_cutting || []).slice().sort();
    const editorial = content.uncommon.statements.slice().sort();
    if (JSON.stringify(computed) !== JSON.stringify(editorial)) {
      throw new Error(
        `aspire content.json: uncommon.statements [${editorial}] must match ` +
          `rankings.cross_cutting [${computed}] from aspire_analyze.py.`
      );
    }
  }

  // Final quadratic-vote results: aggregate item totals only (never voter-
  // level data). Sorted by votes, descending, for the results bars.
  if (qv.items) {
    qv.sorted = [...qv.items].sort((a, b) => b.votes - a.votes);
    qv.maxVotes = Math.max(1, ...qv.items.map((i) => i.votes));
    qv.credits_spent_display = qv.credits_spent.toLocaleString("en-US");
  }

  return { results, content, qv };
};
